messages.content:
Game edukasi Endless Runner "OSI Layer Runner" dengan tema Neon dan tiga lapisan OSI sebagai kategori target. Asumsi: Modem saya tempatkan di kategori Network sesuai definisi baku perangkat pengubah sinyal untuk akses jaringan, dan rintangan dibuat kecil agar mudah dilompati pada tempo Normal.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "osi-layer-runner", title: "OSI Layer Runner", seed: "osi-layer-01",
  theme: { preset: "neon" },

  learning: {
    subject: "Jaringan Komputer",
    concept: "Perangkat jaringan berdasarkan lapisan model OSI (Physical, Data Link, Network)",
    objectives: ["Mengelompokkan perangkat jaringan sesuai lapisan OSI tempatnya bekerja"],
    misconceptions: ["Hub dan Switch dianggap perangkat yang sama, padahal Hub bekerja di Physical dan Switch di Data Link"],
    mode: "category",
    categories: [
      { id: "physical",  label: "Physical",  color: "#00E5FF" },
      { id: "data-link", label: "Data Link", color: "#FF3DF2" },
      { id: "network",   label: "Network",   color: "#FFD93D" }
    ],
    items: [
      { id: "hub",        label: "Hub",           category: "physical",  explain: "Meneruskan sinyal ke semua port tanpa membaca alamat; bekerja di lapisan fisik." },
      { id: "repeater",   label: "Repeater",      category: "physical",  explain: "Memperkuat dan memperpanjang sinyal mentah di lapisan fisik." },
      { id: "kabel-utp",  label: "Kabel UTP",     category: "physical",  explain: "Media transmisi fisik berupa kabel tembaga penghantar sinyal." },
      { id: "switch",     label: "Switch",        category: "data-link", explain: "Meneruskan frame berdasarkan MAC address; bekerja di lapisan data link." },
      { id: "bridge",     label: "Bridge",        category: "data-link", explain: "Menghubungkan dua segmen jaringan berdasarkan alamat MAC." },
      { id: "nic",        label: "Kartu NIC",     category: "data-link", explain: "Antarmuka jaringan yang memiliki alamat MAC; bekerja di data link." },
      { id: "router",     label: "Router",        category: "network",   explain: "Mengarahkan paket antarjaringan berdasarkan alamat IP." },
      { id: "modem",      label: "Modem",         category: "network",   explain: "Mengubah sinyal untuk akses jaringan dan meneruskan paket data." },
      { id: "access-point", label: "Access Point", category: "network",  explain: "Menghubungkan perangkat nirkabel ke jaringan lokal." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "gangguan", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "noise",    w: 80, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
